from flask import Flask, request, jsonify
app = Flask(__name__)

# Define the resources and their default values
resources = [
    {""id"": 1, ""name"": ""Resource 1"", ""value"": 0},
    {""id"": 2, ""name"": ""Resource 2"", ""value"": 0}
]

@app.route('/resources', methods=['GET'])
def get_resources():
    return jsonify(resources)

@app.route('/resources/<int:resource_id>', methods=['GET'])
def get_resource(resource_id):
    for resource in resources:
        if resource['id'] == resource_id:
            return jsonify(resource)
    return jsonify({""error"": ""Resource not found""}), 404

@app.route('/resources', methods=['POST'])
def create_resource():
    new_resource = {""id"": len(resources) + 1, ""name"": """", ""value"": 0}
    resources.append(new_resource)
    return jsonify(new_resource), 201

@app.route('/resources/<int:resource_id>', methods=['PATCH'])
def update_resource(resource_id):
    for resource in resources:
        if resource['id'] == resource_id:
            try:
                patch_data = request.get_json()
                if 'value' in patch_data:
                    resource['value'] += int(patch_data['value'])
            except ValueError as e:
                return jsonify({""error"": str(e)}), 400
            return jsonify(resource)
    return jsonify({""error"": ""Resource not found""}), 404

if __name__ == '__main__':
    app.run(debug=True)
