import os
from PIL import Image

def convert_png_to_svg(input_dir, output_file):
    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.endswith('.png'):
                try:
                    img = Image.open(os.path.join(root, file))
                    rgb_img = img.convert('RGB')
                    svg_img = rgb_img.convert('RGB').convert('P', palette=Image.ADAPTIVE, colors=256).convert('RGBA')
                    svg_img.save(svg_img.filename.split('.')[0] + '.svg', 'SVG')
                except Exception as e:
                    print(f""Error converting {file}: {str(e)}"")
    with open(output_file, 'w') as f:
        pass

if __name__ == ""__main__"":
    import sys
    if len(sys.argv) != 3:
        print(""Usage: python script.py <directory_path> <output_file>"")
        sys.exit(1)
    convert_png_to_svg(sys.argv[1], sys.argv[2])
    sys.exit(0)
