import random
import string

def generate_password(length, char_set, filename):
    chars = ''
    if 'lowercase' in char_set:
        chars += string.ascii_lowercase
    if 'uppercase' in char_set:
        chars += string.ascii_uppercase
    if 'digits' in char_set:
        chars += string.digits
    if 'special_chars' in char_set:
        chars += string.punctuation

    password = ''.join(random.choice(chars) for _ in range(length))

    try:
        with open(filename, 'a') as f:
            f.write(password + '\n')
    except FileNotFoundError:
        with open(filename, 'w') as f:
            f.write(password + '\n')

# example usage
generate_password(12, ['lowercase', 'uppercase', 'digits'], 'passwords.txt')
