import json

class JSONFactory:
    _registry = {}

    @classmethod
    def register(cls, id_):
        def decorator(func):
            cls._registry[id_] = func
            return func
        return decorator

    @classmethod
    def create_instance(cls, id_, **kwargs):
        factory_func = cls._registry.get(id_)
        if factory_func:
            return factory_func(**kwargs)
        else:
            raise ValueError(f""No factory function registered for ID: {id_}"")

class JSONSerializable:
    def to_json(self):
        raise NotImplementedError

@JSONFactory.register('example')
class ExampleClass(JSONSerializable):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def to_json(self):
        return {'name': self.name, 'age': self.age}

def main():
    example_obj = ExampleClass('John Doe', 30)

    # Convert object to JSON string
    json_str = json.dumps(example_obj.to_json())

    # Create new instance from JSON string
    new_instance = JSONFactory.create_instance('example', **json.loads(json_str))

if __name__ == '__main__':
    main()
