def longest_subsequencebelowthreshold(lst, threshold):
    if not lst:
        return []

    n = len(lst)
    dp = [[[] for _ in range(threshold + 1)] for _ in range(n + 1)]

    max_length = 0
    result = []

    for i in range(1, n + 1):
        for j in range(1, threshold + 1):
            if lst[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - lst[i - 1]] + [lst[i - 1]], key=len)
            else:
                dp[i][j] = dp[i - 1][j]

            if len(dp[i][j]) > max_length:
                max_length = len(dp[i][j])
                result = dp[i][j]

    return result']",94,[0],[],True,0,0,0,

