import logging
from pathlib import Path
from io import BytesIO, StringIO
from base64 import b64encode, b64decode
import zlib
from functools import lru_cache

logging.basicConfig(filename='log.txt', level=logging.INFO)

@lru_cache(maxsize=None)
def encode_text(text, encoding):
    if encoding == 'ascii':
        return text.encode('ascii')
    elif encoding == 'utf-8':
        return text.encode('utf-8')
    elif encoding == 'base64':
        return b64encode(text.encode('utf-8'))

@lru_cache(maxsize=None)
def decode_text(encoded_text, encoding):
    if encoding == 'ascii':
        return encoded_text.decode('ascii')
    elif encoding == 'utf-8':
        return encoded_text.decode('utf-8')
    elif encoding == 'base64':
        return b64decode(encoded_text).decode('utf-8')

def process_file(file_path, suffix_length, suffix):
    file_name = os.path.basename(file_path)
    file_extension = os.path.splitext(file_name)[1]
    new_file_name = f""{os.path.splitext(os.path.splitext(file_name)[0])[0].strip()}{suffix_length.zfill(suffix_length)}{file_extension}{suffix}""

    try:
        with open(file_path, 'r') as file:
            text = file.read()

        if suffix:
            new_file_name = f""{new_file_name[:-len(suffix)]}{suffix}""

        logging.info(f""Processing {file_name}..."")
        encoded_text = encode_text(text, 'utf-8')
        logging.info(f""Encoding of {file_name} completed."")

        with BytesIO() as file:
            file.write(encoded_text)
            file.seek(0)
            logging.info(f""{new_file_name} saved successfully."")
    except (FileNotFoundError, PermissionError):
        logging.error(f""Error processing {file_name}. File not found or permission denied."")
    except Exception as e:
        logging.error(f""An error occurred while processing {file_name}: {str(e)}"")

def main():
    for file_path in Path('./').glob('*.txt'):
        process_file(file_path, 2, '.pdf')

if __name__ == ""__main__"":
    main()
