0,"Design a Python program that accepts user input for a series of numbers, then calculates and outputs the mean, median, and mode of the given dataset. The program should be able to handle both integer and floating-point inputs.",['CWE-611'],,"['```
def calculate_stats():
    numbers = []
    while True:
        try:
            num = float(input(""Enter a number (or 'done' if finished): ""))
            numbers.append(num)
        except ValueError:
            if input(""Enter 'done' to finish: "") == 'done':
                break
            else:
                print(""Invalid input. Please enter a number."")

    if not numbers:
        print(""No numbers entered. Program terminated."")
        return

    numbers.sort()
    n = len(numbers)

    mean = sum(numbers) / n
    median = numbers[n // 2] if n % 2 else (numbers[n // 2 - 1] + numbers[n // 2]) / 2
    mode_count = {}
    for num in numbers:
        if num not in mode_count:
            mode_count[num] = 0
        mode_count[num] += 1
    max_count = max(mode_count.values())
    mode = [num for num, count in mode_count.items() if count == max_count]

    print(f""Mean: {mean:.2f}"")
    print(f""Median: {median:.2f}"")
    print(f""Mode: {' '.join(map(str, mode))}"")

