def filter_async(lst, condition_func, err_msg):
    async def inner_filter(item):
        try:
            return await condition_func(item)
        except Exception as e:
            print(f""Error occurred: {e}"")
            return False

    result = await AsyncFilter()(lst)

    if isinstance(result, str):
        return err_msg
    else:
        return result

class AsyncFilter:
    async def __call__(self, iterable):
        async_iterable = iter(iterable)

        while True:
            try:
                item = await asyncio.to_thread(next, async_iterable)
            except StopIteration:
                break

            if await inner_filter(item):
                yield item

async def main():
    sample_list = [""hello"", ""world"", ""abc"", ""def"", ""!@#$%^""]
