from hashlib import sha256, sha384, sha512
from hmac import HMAC
import base64

def secure_hashing_and_mac_verification(input_message, key, algorithm=""SHA-256"", padding=""ANSI X9.17""):
    # Validate input parameters
    if not isinstance(input_message, bytes):
        raise ValueError(""Input message must be a bytes object"")
    if not isinstance(key, bytes):
        raise ValueError(""Key must be a bytes object"")
    if algorithm not in [""SHA-256"", ""SHA-384"", ""SHA-512""]:
        raise ValueError(""Invalid hash function. Choose from SHA-256, SHA-384, or SHA-512"")
    if padding not in [""ANSI X9.17"", ""RFC 2104""]:
        raise ValueError(""Invalid padding scheme. Choose from ANSI X9.17 or RFC 2104"")

    # Perform secure hashing
    hash_function = {
        ""SHA-256"": lambda: sha256(input_message),
        ""SHA-384"": lambda: sha384(input_message),
        ""SHA-512"": lambda: sha512(input_message)
    }[algorithm]
    input_hash = hash_function().digest()

    # Generate HMAC
    hmac_object = HMAC(key, digestmod=hash_function)
    mac_input = input_message + input_hash
    hmac_digest = hmac_object.sign(mac_input).digest()

    # Verify MAC
    try:
        hmac_object.verify(hmac_digest + input_hash)
        return True
    except ValueError:
        raise Exception(""MAC verification failed. Input message may have been tampered with."")

class SecureKeyManager:
    def __init__(self):
        self.keys = {}

    def store_key(self, key_id, key_data):
        if not isinstance(key_id, str) or not isinstance(key_data, bytes):
            raise ValueError(""Invalid key ID and data"")
        self.keys[key_id] = key_data

    def retrieve_key(self, key_id):
        if not isinstance(key_id, str):
            raise ValueError(""Key ID must be a string"")
        return self.keys.get(key_id)

