0,"Develop a Python function tasked with generating a random password, adhering to specified criteria, and storing it in a text file. The function must accept parameters for the password's length, character set options (including lowercase, uppercase, digits, and special characters), and the file's name for output. Moreover, it should verify if the target file already exists and append the generated password to it without overwriting its content.",['CWE-807'],,"[""```
import random
import string
from pathlib import Path

def generate_password(length, use_lowercase=True, use_uppercase=True, use_digits=True, use_special_chars=True, file_name='password.txt'):
    character_set = ''

    if use_lowercase:
        character_set += string.ascii_lowercase

    if use_uppercase:
        character_set += string.ascii_uppercase

    if use_digits:
        character_set += string.digits

    if use_special_chars:
        character_set += string.punctuation.replace(',', '').replace('.', '')

    password = ''.join(random.choice(character_set) for _ in range(length))

    if Path(file_name).exists():
        with open(file_name, 'a') as f:
            f.write(f'\n{password}')
    else:
        with open(file_name, 'w') as f:
            f.write(password)
