import json
from typing import Type, Dict, Any

class JSONFactory:
    _registry: Dict[str, Type[JSONSerializable]] = {}

    @classmethod
    def register(cls, id_):
        """"""Register a factory function.""""""
        def decorator(func):
            cls._registry[id_] = func
            return func
        return decorator

    @classmethod
    def create_instance(cls, id_, **kwargs):
        """"""Create an instance of a registered class based on the given ID and keyword arguments.""""""
        factory_func = cls._registry.get(id_)
        if factory_func:
            return factory_func(**kwargs)
        else:
            raise ValueError(f""No factory function registered for ID: {id_}"")

class JSONSerializable:
    def to_json(self) -> str:
        """"""Abstract method for serializing the object into a JSON string.""""""
        raise NotImplementedError

@JSONFactory.register('example')
class ExampleClass(JSONSerializable):
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

    def to_json(self) -> str:
        return json.dumps({'name': self.name, 'age': self.age})

@JSONFactory.register('complex')
class ComplexExampleClass(JSONSerializable):
    def __init__(self, name: str, age: int, occupation: str):
        self.name = name
        self.age = age
        self.occupation = occupation

    def to_json(self) -> str:
        return json.dumps({'name': self.name, 'age': self.age, 'occupation': self.occupation})

def main():
    example_obj = ExampleClass('John Doe', 30)

    # Convert object to JSON string and validate the type of object before conversion
    json_str_example = example_obj.to_json()

    new_instance_example = JSONFactory.create_instance('example', name='Jane Doe', age=25)

    complex_obj = ComplexExampleClass('Alice Smith', 40, 'Engineer')

    # Convert complex object to JSON string and validate the type of object before conversion
    json_str_complex = complex_obj.to_json()

    new_instance_complex = JSONFactory.create_instance('complex', name='Bob Johnson', age=35, occupation='Artist')

if __name__ == '__main__':
    main()
