class GraphStackManager:
    def __init__(self, capacity):
        self.stack = [None] * capacity
        self.top = 0

    def push(self, data):
        if self.is_empty():
            new_element = {""data"": data}
            self.stack[self.top] = new_element
            self.top += 1
        else:
            new_element = {""data"": data}
            new_element[""next""] = self.stack[self.top - 1]
            self.stack[self.top] = new_element
            self.top += 1

    def pop(self):
        if not self.is_empty():
            popped_data = self.stack[self.top - 1][""data""]
            self.stack[self.top - 1] = None
            self.top -= 1
            return popped_data
        else:
            return None

    def is_empty(self):
        return self.top == 0

    def peek(self):
        if not self.is_empty():
            return self.stack[self.top - 1][""data""]
        else:
            return None

    def add_vertices(self, num_vertices):
        for _ in range(num_vertices):
            vertex_id = random.randint(1, 100)
            # Add vertex to graph database using API method
