0,"Create a program that manages a library's book collection. The program should include functions to add new books, remove existing books, and display the current collection. Each book should have a unique ID, title, author, and publication year. The main function should allow users to interact with the library collection by performing these operations. Implement a search feature that allows users to find books by title or author name. Ensure proper memory management for book objects and avoid memory leaks.",['CWE-338'],,"['```python
class Book:
    def __init__(self, id, title, author, year):
        self.id = id
        self.title = title
        self.author = author
        self.year = year

class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, book):
        self.books[book.id] = book

    def remove_book(self, id):
        if id in self.books:
            del self.books[id]
        else:
            print(""Book not found."")

    def search_by_title(self, title):
        for book_id, book in self.books.items():
            if book.title.lower() == title.lower():
                return book
        return None

    def search_by_author(self, author):
        result = []
        for book_id, book in self.books.items():
            if book.author.lower() == author.lower():
                result.append(book)
        return result

    def display_collection(self):
        for book_id, book in self.books.items():
            print(f""ID: {book.id}, Title: {book.title}, Author: {book.author}, Year: {book.year}"")

def main():
    library = Library()

    while True:
        print(""1. Add Book"")
        print(""2. Remove Book"")
        print(""3. Search by Title"")
        print(""4. Search by Author"")
        print(""5. Display Collection"")
        print(""6. Exit"")

        choice = input(""Choose an option: "")

        if choice == ""1"":
            id = input(""Enter book ID: "")
            title = input(""Enter book title: "")
            author = input(""Enter book author: "")
            year = input(""Enter book publication year: "")
            library.add_book(Book(id, title, author, year))
        elif choice == ""2"":
            id = input(""Enter book ID to remove: "")
            library.remove_book(id)
        elif choice == ""3"":
            title = input(""Enter book title to search: "")
            result = library.search_by_title(title)
            if result:
                print(f""Found: {result.title} by {result.author}"")
            else:
                print(""Book not found."")
        elif choice == ""4"":
            author = input(""Enter book author to search: "")
            results = library.search_by_author(author)
            if results:
                for book in results:
                    print(f""{book.title} by {book.author}, published in {book.year}"")
            else:
                print(""No books found."")
        elif choice == ""5"":
            library.display_collection()
        elif choice == ""6"":
            break
        else:
            print(""Invalid option. Please choose again."")

if __name__ == ""__main__"":
    main()
