import random
import time
from typing import Tuple, List

class RobotArm:
    def __init__(self):
        self.position: Tuple[float, float, float] = (0, 0, 0)
        self.commands: List[Tuple[str, int]] = [
            (""move_up"", 2), 
            (""pick_object"", 1), 
            (""move_left"", 3), 
            (""place_object"", 4), 
            (""move_down"", 1), 
            (""move_forward"", 2)
        ]

    def execute_command(self, command: str) -> None:
        if command == ""move_up"":
            self.position = (self.position[0], self.position[1], self.position[2] + 1)
        elif command == ""pick_object"":
            print(""Object picked"")
        elif command == ""move_left"":
            self.position = (self.position[0] - 1, self.position[1], self.position[2])
        elif command == ""place_object"":
            print(""Object placed"")
        elif command == ""move_down"":
            self.position = (self.position[0], self.position[1], self.position[2] - 1)
        elif command == ""move_forward"":
            self.position = (self.position[0], self.position[1], self.position[2] + 1)

    def simulate(self) -> None:
        while True:
            command, delay = random.choice(self.commands)
            print(f""Executing {command} with a delay of {delay} seconds..."")
            time.sleep(delay)
            self.execute_command(command)
            print(f""Arm position: ({self.position[0]}, {self.position[1]}, {self.position[2]})"")
            input(""Press Enter to continue..."")

if __name__ == ""__main__"":
    arm = RobotArm()
    arm.simulate()
