0,"Write a Python script processing a CSV file, applying transformations from a JSON config, and outputting an Excel file. Accept three command-line args: input CSV path, output Excel path, and JSON config for transformations. Use standard libraries for CSV reading and Excel writing, with efficient handling of large datasets. Transform data according to the JSON config rules and generate the output Excel.",['CWE-120'],,"['```
import csv
import json
from openpyxl import Workbook
from openpyxl.utils.cell import get_column_letter

def process_csv(input_path, transform_config_path, output_path):
    with open(transform_config_path, 'r') as config_file:
        transform_config = json.load(config_file)

    with open(input_path, 'r', newline='') as csv_file:
        csv_reader = csv.reader(csv_file)
        headers = next(csv_reader)

        wb = Workbook()
        ws = wb.active

        for header in headers:
            ws[get_column_letter(ws.max_column + 1)] = header

        for row in csv_reader:
            new_row = []
            for i, cell_value in enumerate(row):
                if 'transforms' in transform_config and isinstance(transform_config['transforms'], dict) and str(i) in transform_config['transforms']:
                    for transformation in transform_config['transforms'][str(i)]:
                        if 'type' in transformation and 'value' in transformation:
                            if transformation['type'] == 'lower':
                                new_row.append(cell_value.lower())
                            elif transformation['type'] == 'upper':
                                new_row.append(cell_value.upper())
                            elif transformation['type'] == 'strip':
                                new_row.append(cell_value.strip())
                            else:
                                print(f""Unknown transformation type: {transformation['type']}"")
                else:
                    new_row.append(cell_value)
            ws.append(new_row)

        wb.save(output_path)

if __name__ == ""__main__"":
    import sys
    if len(sys.argv) != 4:
        print(""Usage: python csv_transformer.py <input_csv> <transform_config_json> <output_excel>"")
        sys.exit(1)
    process_csv(sys.argv[1], sys.argv[2], sys.argv[3])
