import json
import base64
from OpenSSL import RAND_bytes
from cryptography.hazmat.primitives.ciphers import CipherContext, algorithms, modes
from cryptography.hazmat.primitives import padding

def secureCopyBufferChunks(buffer_chunks, cipher_mode, oauth2_access_token):
    if not all(isinstance(chunk, (bytes, bytearray)) for chunk in buffer_chunks):
        return ""Invalid buffer chunks provided""

    new_buffer = bytearray()
    iv = None

    def validate_access_token(oauth2_access_token):
        try:
            json_data = json.loads(oauth2_access_token)
            required_fields = ['access_token', 'expires_in', 'token_type']
            if not all(field in json_data for field in required_fields):
                return ""OAuth2 access token missing required fields""
            if not isinstance(json_data['expires_in'], int) or json_data['expires_in'] < 0:
                return ""Invalid expires_in value""
            if json_data['token_type'] != 'Bearer':
                return ""Invalid token type""
        except Exception as e:
            return str(e)

        return True

    def encrypt_chunk(chunk):
        nonlocal iv
        ctx = CipherContext(algorithms[cipher_mode], modes.ECB())
        padded_data = padding.PKCS7().pad(chunk)
        encrypted_padded_data = base64.b64encode(ctx.encrypt(padded_data))
        new_buffer.extend(encrypted_padded_data)

    for chunk in buffer_chunks:
        if cipher_mode == 'DES_EDE':
            iv = RAND_bytes(8).decode('utf-8')
            ctx = CipherContext(algorithms.DESede(), modes.ECB())
            encrypted_chunk = base64.b64encode(ctx.encrypt(chunk))
            new_buffer.extend(encrypted_chunk)
        else:
            try:
                ctx = CipherContext(getattr(algorithms, cipher_mode), modes.ECB())
                encrypted_chunk = base64.b64encode(ctx.encrypt(chunk))
                new_buffer.extend(encrypted_chunk)
            except Exception as e:
                return str(e)

    if not validate_access_token(oauth2_access_token):
        return ""OAuth2 access token validation failed""

    return bytes(new_buffer)

