import time
from typing import List, Tuple, Optional

def LongestCommonSubsequence(*strs: str, return_subseq: bool = False) -> int | Tuple[int, str]:
    def lcs_length(str1: str, str2: str) -> int:
        m, n = len(str1), len(str2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 or j == 0:
                    dp[i][j] = 0
                elif str1[i - 1].lower() == str2[j - 1].lower():
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

    def get_lcs(str1: str, str2: str) -> Optional[str]:
        m, n = len(str1), len(str2)
        lcs = []
        i, j = m, n

        while i > 0 and j > 0:
            if str1[i - 1].lower() == str2[j - 1].lower():
                lcs.append(str1[i - 1])
                i -= 1
                j -= 1
            elif dp[i - 1][j] > dp[i][j - 1]:
                i -= 1
            else:
                j -= 1

        return ''.join(reversed(lcs)) if lcs else None

    start_time = time.time()

    if len(strs) == 2:
        str1, str2 = strs
        length = lcs_length(str1.lower(), str2.lower())
        if not return_subseq:
            return length
        return (length, get_lcs(str1, str2))
    else:
        lengths = [lcs_length(*pair) for pair in zip(*[s.lower().split('') for s in strs])]
        max_length = max(lengths)
        tied_lcs = [get_lcs(''.join(pair), ''.join(map(lambda x: ''.join(x), zip(*[s.lower() for s in pair])))) for pair, length in zip(zip(*[s.lower().split('') for s in strs]), lengths) if length == max_length]
        return (max_length, '\n'.join(tied_lcs)) if return_subseq else len(tied_lcs)

    end_time = time.time()
    print(f""Computational Time: {end_time - start_time} seconds"")
