import tkinter as tk
from tkinter import messagebox
import redis
import time

# Set up Redis cache
redis_client = redis.Redis(host='localhost', port=6379, db=0)

class WeatherApp:
    def __init__(self):
        self.root = tk.Tk()
        self.favorites = []

    def get_weather_data(self, cities):
        weather_data = {}
        for city in cities.split(','):
            city = city.strip().lower()
            if not redis_client.get(city):
                try:
                    api_response = requests.get(f'http://api.openweathermap.org/data/2.5/weather?q={city}&units=metric')
                    api_response.raise_for_status()
                    weather_data[city] = json.loads(api_response.content.decode('utf-8'))
                    redis_client.set(city, json.dumps(weather_data[city]))
                except requests.exceptions.RequestException as e:
                    print(f""Error retrieving data for {city}: {e}"")
            else:
                weather_data[city] = json.loads(redis_client.get(city).decode('utf-8'))

        return weather_data

    def display_weather(self, weather_data):
        for city, data in weather_data.items():
            temperature = data['main']['temp']
            humidity = data['main']['humidity']
            wind_speed = data['wind']['speed']

            print(f""{city}: Temperature {temperature}°C, Humidity {humidity}% Wind Speed {wind_speed}m/s"")

    def set_favorites(self):
        self.favorites = [city.strip().lower() for city in input(""Enter your favorite cities (comma-separated): "").split(',')

    def check_weather(self):
        if not self.favorites:
            messagebox.showinfo(""Error"", ""Please set your favorite cities first!"")
        else:
            weather_data = self.get_weather_data(', '.join(self.favorites))
            self.display_weather(weather_data)

    def rate_limit(self, api_call_time):
        time.sleep(api_call_time)
        print(f""Rate limited. Waiting {api_call_time} seconds before making next API call."")

    def main(self):
        self.set_favorites()
        while True:
            try:
                self.check_weather()
                break
            except requests.exceptions.RequestException as e:
                print(f""Error: {e}"")
                time.sleep(1)
        self.root.mainloop()

if __name__ == ""__main__"":
    weather_app = WeatherApp()
    weather_app.main()
```
