import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization
from cryptography.exceptions import InvalidSignature

def encrypt_decrypt(message: str, key_type: str, key_size: int, cipher_mode: str, padding_scheme: str) -> dict:
    if not message or not isinstance(message, str):
        raise ValueError(""Invalid input message"")

    if not key_type in ['AES', 'RSA', 'ECC']:
        raise ValueError(""Unsupported key type. Choose from AES, RSA, ECC"")

    if key_size % 8 != 0:
        raise ValueError(""Key size must be a multiple of 8 bytes."")

    if cipher_mode not in ['GCM', 'CBC', 'CTR']:
        raise ValueError(""Invalid cipher mode. Choose from GCM, CBC, CTR"")

    if padding_scheme not in ['PKCS#7', 'OAEP']:
        raise ValueError(""Invalid padding scheme. Choose from PKCS#7, OAEP"")

    if key_type == 'AES':
        key = os.urandom(key_size // 8)
        cipher = Cipher(algorithms.AES(key), modes.GCM(b'\00' * 16), backend=default_backend())
        encrypted_message = base64.b64encode(cipher.encryptor().update(message.encode()) + cipher.encryptor().hexdigest())

    elif key_type == 'RSA':
        private_key = serialization.load_pem_private_key(key, password=None, backend=default_backend())
        public_key = private_key.public_key()
        encryptor = public_key.encryptor()
        encrypted_message = base64.b64encode(encryptor.update(message.encode()) + encryptor.finalize())

    elif key_type == 'ECC':
        private_key = serialization.load_pem_private_key(key, password=None, backend=default_backend())
        public_key = private_key.public_key()
        encryptor = public_key.encryptor()
        encrypted_message = base64.b64encode(encryptor.update(message.encode()) + encryptor.finalize())

    if padding_scheme == 'PKCS#7':
        padded_message = pkcs_pad(message)
    elif padding Scheme == 'OAEP':
        padded_message = oaep_pad(message)

    if cipher_mode == 'GCM':
        signature = hmac.new(key, message.encode(), hashes.SHA256).digest()
    elif cipher_mode == 'CBC' or 'CTR':
        signature = hmac.new(key, message.encode(), hashes.SHA256).digest()

    return {'encrypted_message': encrypted_message, 'signature': base64.b64encode(signature)}


def decrypt(encrypted_message: str, key_type: str, key_size: int, cipher_mode: str, padding_scheme: str) -> dict:
    if not isinstance(encrypted_message, bytes):
        raise ValueError(""Invalid input message"")

    if not key_type in ['AES', 'RSA', 'ECC']:
        raise ValueError(""Unsupported key type. Choose from AES, RSA, ECC"")

    if key_size % 8 != 0:
        raise ValueError(""Key size must be a multiple of 8 bytes."")

    if cipher_mode not in ['GCM', 'CBC', 'CTR']:
        raise ValueError(""Invalid cipher mode. Choose from GCM, CBC, CTR"")

    if padding_scheme not in ['PKCS#7', 'OAEP']:
        raise ValueError(""Invalid padding scheme. Choose from PKCS#7, OAEP"")

    if key_type == 'AES':
        key = os.urandom(key_size // 8)
        cipher = Cipher(algorithms.AES(key), modes.GCM(b'\00' * 16), backend=default_backend())
        decrypted_message = cipher.decryptor().update(base64.b64decode(encrypted_message)) + cipher.decryptor().finalize()

    elif key_type == 'RSA':
        private_key = serialization.load_pem_private_key(key, password=None, backend=default_backend())
        public_key = private_key.public_key()
        decryptor = public_key.decryptor()
        decrypted_message = decryptor.update(base64.b64decode(encrypted_message)) + decryptor.finalize()

    elif key_type == 'ECC':
        private_key = serialization.load_pem_private_key(key, password=None, backend=default_backend())
        public_key = private_key.public_key()
        decryptor = public_key.decryptor()
        decrypted_message = decryptor.update(base64.b64decode(encrypted_message)) + decryptor.finalize()

    if padding_scheme == 'PKCS#7':
        decrypted_message = pkcs_unpad(decrypted_message)
    elif padding Scheme == 'OAEP':
        decrypted_message = oaep_unpad(decrypted_message)

    return {'decrypted_message': decrypted_message}


def hmac(key: bytes, message: str) -> bytes:
    if not key or not isinstance(key, bytes):
        raise ValueError(""Invalid input key"")

    if not message or not isinstance(message, str):
        raise ValueError(""Invalid input message"")

    signature = hashes.new(hashes.SHA256())
    signature.update(key)
    signature.update(message.encode())

    return base64.b64encode(signature.finalize()).decode()


def pkcs_pad(message: str) -> bytes:
    if not message or not isinstance(message, str):
        raise ValueError(""Invalid input message"")

    pad_len = 16 - (len(message.encode()) % 16)
    padded_message = message.encode() + os.urandom(pad_len)
    return base64.b64encode(padded_message).decode()


def oaep_pad(message: str) -> bytes:
    if not message or not isinstance(message, str):
        raise ValueError(""Invalid input message"")

    pad_len = 16 - (len(message.encode()) % 16)
    padded_message = message.encode() + os.urandom(pad_len)
    return base64.b64encode(padded_message).decode()


def pkcs_unpad(padded_message: str) -> bytes:
    if not padded_message or not isinstance(padded_message, str):
        raise ValueError(""Invalid input message"")

    unpadded_message = base64.b64decode(padded_message)
    pad_len = 16 - (len(unpadded_message) % 16)
    return unpadded_message[:-pad_len].decode()


def oaep_unpad(padded_message: str) -> bytes:
    if not padded_message or not isinstance(padded_message, str):
        raise ValueError(""Invalid input message"")

    unpadded_message = base64.b64decode(padded_message)
    pad_len = 16 - (len(unpadded_message) % 16)
    return unpadded_message[:-pad_len].decode()
