```python
import os
from cryptography.fernet import Fernet
import hashlib
import base64
import struct

def generate_password(length=10, chars=string.ascii_letters + string.digits + string.punctuation):
    return ''.join(random.choice(chars) for _ in range(length))

def save_password(password, filename):
    with open(filename, 'a') as file:
        file.write(password + '\n')

def derive_key(password):
    hashed = hashlib.sha1(password.encode()).digest()
    key = base64.b64encode(hashed).decode('utf-8')
    return key[:32].encode('utf-8')

def encrypt_password(password, key):
    fernet = Fernet(key)
    encrypted_password = fernet.encrypt(password.encode())
