import os
from collections import Counter
import re
import json
import csv
import logging
import threading
import time

class TextProcessor:
    def __init__(self):
        self.logger = logging.getLogger('TextProcessor')
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())
        self.stop_words = set(['the', 'is', 'and', 'a', 'an', 'of'])

    def file_path_validation(self, file_path):
        if not os.path.exists(file_path):
            return f""Error: File '{file_path}' does not exist.""
        elif not os.access(file_path, os.R_OK):
            return f""Error: Unable to open file '{file_path}' for reading.""
        else:
            return None

    def word_count(self, file_path, target_word):
        try:
            with open(file_path, 'r') as file:
                text = file.read()
                words = re.findall(r'\b\w+\b', text.lower())
                count = sum(1 for word in words if word == target_word.lower())
                return count
        except Exception as e:
            self.logger.error(f""Error processing file '{file_path}': {str(e)}"")
            return None

    def case_insensitive_count(self, file_path, target_word):
        try:
            with open(file_path, 'r') as file:
                text = file.read()
                words = re.findall(r'\b\w+\b', text.lower())
                count = sum(1 for word in set(words) if word == target_word.lower() or word == target_word.upper())
                return count
        except Exception as e:
            self.logger.error(f""Error processing file '{file_path}': {str(e)}"")
            return None

    def process_file(self, file_path):
        try:
            with open(file_path, 'r') as file:
                text = file.read()
                words = re.findall(r'\b\w+\b', text.lower())
                count_dict = Counter(words)
                stop_words_count = sum(1 for word in count_dict if word in self.stop_words)
                total_word_count = len(count_dict) - stop_words_count
                target_word_count = self.case_insensitive_count(file_path, 'target_word')
                percentage = (target_word_count / total_word_count) * 100 if total_word_count > 0 else 0
                return {
                    ""word_count"": len(count_dict),
                    ""stop_words_count"": stop_words_count,
                    ""total_word_count"": total_word_count,
                    ""target_word_count"": target_word_count,
                    ""percentage"": percentage
                }
        except Exception as e:
            self.logger.error(f""Error processing file '{file_path}': {str(e)}"")
            return None

    def analyze_file(self, file_path):
        result = self.process_file(file_path)
        if result is not None:
            print(json.dumps(result))
        else:
            print(""Error occurred during file analysis."")

    def start_processing(self, file_path):
        try:
            with open(file_path, 'r') as file:
                text = file.read()
                words = re.findall(r'\b\w+\b', text.lower())
                threads = []
                line_count = 0
                for i in range(0, len(words), 10000):  # Split into chunks of 10k lines each
                    chunk = words[i:i+10000]
                    thread = threading.Thread(target=self.process_chunk, args=(chunk,))
                    thread.start()
                    threads.append(thread)
                    line_count += len(chunk)

                for thread in threads:
                    thread.join()

            print(f""Processed {line_count} lines."")
        except Exception as e:
            self.logger.error(f""Error processing file '{file_path}': {str(e)}"")

    def process_chunk(self, chunk):
        try:
            count_dict = Counter(chunk)
            stop_words_count = sum(1 for word in count_dict if word in self.stop_words)
            total_word_count = len(count_dict) - stop_words_count
            print(f""Processing {len(chunk)} lines..."")

        except Exception as e:
            self.logger.error(f""Error processing chunk: {str(e)}"")

    def show_progress(self, file_path):
        try:
            with open(file_path, 'r') as file:
                text = file.read()
