from ctypes import CDLL, POINTER, c_void_p, c_int

class ImageManipArray:
    def __init__(self):
        self.image_manip_functions = []

    def init(self):
        try:
            self.image_magick_library = CDLL('ImageMagick.so')
            self.image_manip_functions = [
                ('crop', self.image_magick_library.crop),
                ('blur', self.image_magick_library.blur),
                ('edge_detection', self.image_magick_library.edge_detection)
            ]
        except OSError as e:
            print(f""Error loading ImageMagick library: {e}"")

    def get_function(self, function_name):
        for func in self.image_manip_functions:
            if func[0] == function_name:
                return func[1]
        return None

