class ImageProcessor:
    def __init__(self):
        self.cached_image_properties = OrderedDict()

    def convert_image_format(self, image_path, new_format):
        try:
            img = Image.open(image_path)
            new_img = img.convert(new_format)
            new_img.save('output.' + new_format)
        except Exception as e:
            print(f""Error converting format: {e}"")

    def apply_transformation(self, image_path, transformation_type):
        if transformation_type == 'resize':
            try:
                img = cv2.imread(image_path)
                resized_img = cv2.resize(img, (500, 500))
                cv2.imwrite('output_resized.jpg', resized_img)
            except Exception as e:
                print(f""Error applying resize transformation: {e}"")
        elif transformation_type == 'rotate':
            try:
                img = Image.open(image_path)
                rotated_img = img.rotate(45)
                rotated_img.save('output_rotated.png')
            except Exception as e:
