import statistics as st
from collections import Counter

def get_data():
    while True:
        try:
            data = input(""Enter a series of numbers separated by spaces (integer or floating-point): "")
            numbers = list(map(float, data.split()))
            return numbers
        except ValueError:
            print(""Invalid input. Please enter only numeric values."")

def calculate_mean(numbers):
    return st.mean(numbers)

def calculate_median(numbers):
    return st.median(numbers)

def calculate_mode(numbers):
    count = Counter(numbers)
    max_count = max(count.values())
    mode_val = [num for num, freq in count.items() if freq == max_count]
    if len(mode_val) == len(numbers):
        return ""No mode""
    else:
        return mode_val

def main():
    numbers = get_data()

    mean_result = calculate_mean(numbers)

    median_result = calculate_median(numbers)

    mode_result = calculate_mode(numbers)

    print(f""Mean: {mean_result}"")
    print(f""Median: {median_result}"")
    print(f""Mode: {mode_result}"")

if __name__ == ""__main__"":
    main()
