def secureCopyBufferChunks(source_buffer, dest_buffer, start_index_source, end_index_source, start_index_dest, chunk_size, cipher_mode='DES_EDE', access_token=None):
    if not isinstance(source_buffer, bytes) or not isinstance(dest_buffer, bytes):
        raise ValueError(""Input buffers must be of type bytes."")
    if not isinstance(start_index_source, int) or not isinstance(end_index_source, int) or not isinstance(start_index_dest, int) or not isinstance(chunk_size, int):
        raise ValueError(""Start/End indices and chunk size must be integers."")
    if start_index_source < 0 or end_index_source < 0 or start_index_dest < 0:
        raise ValueError(""Indices cannot be negative."")
    if len(source_buffer) <= start_index_source or len(dest_buffer) <= start_index_dest:
        raise ValueError(""Start indices exceed buffer sizes."")
    if chunk_size > len(source_buffer):
        raise ValueError(""Chunk size exceeds source buffer size."")

    if cipher_mode == 'AES':
        from Crypto.Cipher import AES
        key = bytes(16)  # Initialize with a random key of 16 bytes
        cipher_ctx = AES.new(key, AES.MODE_CBC)
        encrypted_chunks = []

        while start_index_source < end_index_source:
            chunk = source_buffer[start_index_source:start_index_source + chunk_size]
            if cipher_mode == 'AES':
                encrypted_chunk = cipher_ctx.encrypt(chunk)
                encrypted_chunks.append(encrypted_chunk)
            start_index_source += chunk_size
        dest_buffer[start_index_dest:start_index_dest] = b''.join([chunk for chunk in encrypted_chunks])

    elif cipher_mode == 'DES_EDE':
        from Crypto.Cipher import DES3
        key = bytes(24)  # Initialize with a random key of 24 bytes
        cipher_ctx = DES3.new(key, DES3.MODE_CBC)
        encrypted_chunks = []

        while start_index_source < end_index_source:
            chunk = source_buffer[start_index_source:start_index_source + chunk_size]
            if cipher_mode == 'DES_EDE':
                encrypted_chunk = cipher_ctx.encrypt(chunk)
                encrypted_chunks.append(encrypted_chunk)
            start_index_source += chunk_size
        dest_buffer[start_index_dest:start_index_dest] = b''.join([chunk for chunk in encrypted_chunks])

    if access_token is not None:
        try:
            import json
            token_dict = json.loads(access_token)
            if 'access_token' not in token_dict or 'expires_in' not in token_dict:
                raise ValueError(""Invalid OAuth2 access token."")
        except json.JSONDecodeError:
            raise ValueError(""Invalid JSON format in the access token."")

    return dest_buffer
