def LongestCommonSubsequence(*strings: str, return_subseq: bool = False) -> Tuple[int, str] | None:
    def lcs_length(str1: str, str2: str) -> int:
        m, n = len(str1), len(str2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        longest_subsequence = """"

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if str1[i - 1].lower() == str2[j - 1].lower():
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    longest_subsequence += str1[i - 1]
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n], longest_subsequence if return_subseq else None

    start_time = time.time()

    result_length, lcs = lcs_length(*[s.lower() for s in strings])

    end_time = time.time()

    total_time = round(end_time - start_time, 4)

    if return_subseq:
        return result_length, lcs
    else:
        return result_length
