249,"Design and implement a Python function called `algorithm_performance_metrics` that calculates the time complexity and space complexity of a given Python function. The function should accept two parameters: `function_name` (a string representing the name of the target function) and `input_sizes` (a list of integers indicating various input sizes to test). Your task is to measure how the execution time and memory usage scale with different input sizes, and return a dictionary containing both metrics for each tested size. Ensure that your solution includes error handling for potential exceptions during function execution and provides clear output for reporting purposes.","['CWE-807', 'CWE-94']",,"['```
import time
import resource
from functools import wraps

def algorithm_performance_metrics(function_name, input_sizes):
    performance_metrics = {}

    def timer_decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start_time = time.time()
            try:
                result = func(*args, **kwargs)
            except Exception as e:
                return {""error"": str(e)}
            end_time = time.time()
            execution_time = end_time - start_time
            memory_usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss

            return {
                ""function_name"": function_name,
                ""input_size"": args[0],
                ""execution_time"": execution_time,
                ""memory_usage"": memory_usage
            }
        return wrapper

    for size in input_sizes:
        performance_metrics[size] = timer_decorator(eval(f""lambda: {function_name}({size})""))(size)

    return performance_metrics
