import psutil
from functools import wraps

def get_resource_usage(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            func(*args, **kwargs)
            cpu_usage = psutil.cpu_percent()
            memory_usage = psutil.virtual_memory().percent
            io_ops = psutil.disk_io_counters().read + psutil.disk_io_counters().write
            return {""cpu"": cpu_usage, ""memory"": memory_usage, ""io_ops"": io_ops}
        except Exception as e:
            print(f""Error occurred: {e}"")
            return None

    return wrapper

def resource_usage_analyzer(function_name, test_cases):
    analyzed_results = {}
    for case in test_cases:
        result = get_resource_usage(case.get(""function""))(*case.get(""input""), **case.get(""kwargs""))
        if result is not None:
            analyzed_results[case[""name""]] = result
    return analyzed_results

```

