        super().__init__()

    def run(self):
        time.sleep(Timer.SERVICE_DELAY)
        print(""Service started"")

class CryptoService:
    def __init__(self):
        self.crypto_objects = self.load_crypto_objects()
        self.timer = None

    @staticmethod
    def load_crypto_objects():
        return [
            {'name': 'SHA256', 'hash_function': SHA256.new},
            {'name': 'AES', 'cipher': AES.new}
        ]

    def start_service(self):
        self.timer = TimerTask()
        self.timer.start()

    def stop_service(self):
        self.timer.cancel()

