def compress(data, level=6, algorithm='lzma'):
    if algorithm == 'lzma':
        compressed_data = zlib.compress(data, level)
    elif algorithm == 'zlib':
        compressed_data = zlib.compress(data)
    else:
        raise ValueError('Invalid compression algorithm')

    return compressed_data

def decompress(compressed_data, format='png', algorithm='lzma'):
    if algorithm == 'lzma':
        data = zlib.decompress(compressed_data)
    elif algorithm == 'zlib':
        data = zlib.decompress(compressed_data)
    else:
        raise ValueError('Invalid compression algorithm')

    return data

def generate_packet(data, sequence_number=0, priority='even'):
    if priority not in ['even', 'odd']:
        raise ValueError('Invalid priority tag')

    packet_header = f""{sequence_number}:{priority}""
    encoded_payload_length = len(data).bit_length()
    payload_data = random.getrandbits(encoded_payload_length)

    return (packet_header + str(payload_data)).encode()

def validate_inputs(compression_level, data_size, algorithm, decompress_format):
    if not isinstance(compression_level, int) or compression_level < 0:
        raise ValueError('Invalid compression level')
    if not isinstance(data_size, int) or data_size < 0:
        raise ValueError('Invalid data size')
    if algorithm not in ['lzma', 'zlib']:
        raise ValueError('Invalid compression algorithm')
    if decompress_format not in ['png', 'gif']:
