import json
import random

def sum_dicts(dict1, dict2):
    for key in set(list(dict1.keys()) + list(dict2.keys())):
        if key in dict1 and key in dict2:
            dict1[key] += dict2[key]
        else:
            dict1[key] = dict2.get(key, 0)
    return dict1

def first_dicts(dict1, dict2):
    for key in set(list(dict1.keys()) + list(dict2.keys())):
        if key in dict1 and key in dict2:
            dict1[key] = dict2[key]
        else:
            dict1[key] = dict2.get(key, 0)
    return dict1

def random_dicts(dict1, dict2):
    for key in set(list(dict1.keys()) + list(dict2.keys())):
        if key in dict1 and key in dict2:
            values = [dict1[key], dict2[key]]
            random_value = random.choice(values)
            dict1[key] = random_value
        else:
            dict1[key] = dict2.get(key, 0)
    return dict1

def parse_and_generate(json_list, key_handling_rule='sum', min_value=0, max_value=100):
    merged_dict = {}

    if key_handling_rule == 'sum':
        for json_obj in json_list:
            merged_dict = sum_dicts(merged_dict, json_obj)
    elif key_handling_rule == 'first':
        for json_obj in json_list:
            merged_dict = first_dicts(merged_dict, json_obj)
    elif key_handling_rule == 'random':
        for json_obj in json_list:
            merged_dict = random_dicts(merged_dict, json_obj)
    else:
        raise ValueError(""Invalid key handling rule. Choose from ['sum', 'first', 'random']"")

    return min(int(random.randint(min_value, max_value)) // (max_value - min_value + 1), len(merged_dict) + 1)
