from typing import Callable, Dict, Type

class DateFactory:
    converters: Dict[str, Callable] = {}

    @classmethod
    def register(cls, id: str):
        def decorator(func: Callable) -> Callable:
            cls.converters[id] = func
            return func

        return decorator

    @classmethod
    def create_instance(cls, id: str, **kwargs) -> Type['DateConverter']:
        if id not in cls.converters:
            raise ValueError(f""No converter registered with ID {id}"")
        converter_class = cls._get_converter_class(id)
        return converter_class(**kwargs)

    @classmethod
    def _get_converter_class(cls, id: str) -> Type['DateConverter']:
        for name in dir(cls):
            obj = getattr(cls, name)
            if isinstance(obj, type) and issubclass(obj, DateConverter) and obj.id == id:
                return obj
        raise ValueError(f""No converter class found with ID {id}"")

class DateConverter:
    id: str

class DateConverterForISOFormat(DateConverter):
    id = ""iso""

    @classmethod
    def to_string(cls, date) -> str:
        return f""{date.year}-{str(date.month).zfill(2)}-{str(date.day).zfill(2)}""

class DateConverterForYMDFormat(DateConverter):
    id = ""ymd""

    @classmethod
    def to_string(cls, date) -> str:
        return f""{str(date.year).zfill(4)}-{str(date.month).zfill(2)}-{str(date.day).zfill(2)}""


def main():
