import logging
import os
import subprocess
import time
from threading import Thread
from queue import Queue

# Set up logging
logging.basicConfig(filename='command_logs.log', level=logging.INFO)
log = logging.getLogger()

class CommandExecutor:
    def __init__(self):
        self.command_history = []
        self.process_monitoring = []

    def execute_command(self, command):
        try:
            output = subprocess.check_output(command.split())
            log.info(f""Executed command: {command} | Output: {output.decode()}"")
        except subprocess.CalledProcessError as e:
            log.error(f""Command execution failed with error code {e.returncode}: {command}"")

    def execute_multiple_commands(self, commands):
        for i, command in enumerate(commands):
            if i > 0:
                self.wait_for_previous_command()
            self.execute_command(command)

    def wait_for_previous_command(self):
        while True:
            time.sleep(1)
            processes = [p for p in self.process_monitoring if p.poll() is None]
            if not processes:
                break

    def monitor_processes(self, command):
        process = subprocess.Popen(command.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        self.process_monitoring.append(process)
        Thread(target=self.wait_for_process_termination).start()

    def wait_for_process_termination(self):
        while True:
            time.sleep(1)
            processes = [p for p in self.process_monitoring if p.poll() is None]
            for process in processes:
                if process.poll() != 0:
                    log.error(f""Process terminated with error code {process.poll()}: {process.args}"")
                    break
            else:
                break

    def validate_input(self, command):
        # Validate user input to ensure safe commands are executed
        return True  # Replace this with actual validation logic

    def start_command_execution(self):
        while True:
            user_input = input(""Enter a command (or 'q' to quit): "")
            if user_input.lower() == 'q':
                break
            if not self.validate_input(user_input):
                log.error(f""Invalid command: {user_input}"")
                continue
            self.command_history.append(user_input)
            self.execute_multiple_commands([user_input])
        print(""Command execution terminated."")

if __name__ == ""__main__"":
    executor = CommandExecutor()
    executor.start_command_execution()
