import random
from typing import Dict, List, Tuple
import networkx as nx
import multiprocessing

def generate_graph(min_vertices: int, max_vertices: int, min_edges_per_vertex: float, max_edges_per_vertex: float, 
                    probability_distribution: str, enable_self_loops: bool, attribute_types: Dict[str, type], 
                    performance_optimization: bool) -> Tuple[nx.Graph, Dict]:
    if min_vertices <= 0 or max_vertices <= 0:
        raise ValueError(""Minimum and maximum vertex count must be positive."")

    graph = nx.Graph()
    attributes = {}
    edge_weights = {}

    def generate_vertex_label() -> str:
        return f""Vertex {random.randint(1, 1000)}""

    def generate_edge_weight() -> float:
        return random.uniform(-10.0, 10.0)

    if performance_optimization:
        with multiprocessing.Pool(processes=multiprocessing.cpu_count()) as pool:
            vertices = list(pool.map(lambda: (generate_vertex_label(), dict((f""{k}_{i+1}"", random.choice(list(v.values())) for k, v in attribute_types.items() for i in range(random.randint(1, 5)))), enable_self_loops), range(min_vertices, max_vertices + 1)))
            edges = list(pool.starmap(lambda vertex: [(vertex[0], generate_vertex_label(), generate_edge_weight()) if random.random() < min_edges_per_vertex else () for _ in range(max(int((max_edges_per_vertex - min_edges_per_vertex) * random.random() + min_edges_per_vertex), 1))], vertices))
    else:
        vertices = []
        edges = []

        for i in range(min_vertices, max_vertices + 1):
            label = generate_vertex_label()
            attributes[label] = dict((f""{k}_{i+1}"", random.choice(list(v.values())) for k, v in attribute_types.items() for _ in range(random.randint(1, 5))))
            vertices.append(label)

        for vertex in vertices:
            for _ in range(max(int((max_edges_per_vertex - min_edges_per_vertex) * random.random() + min_edges_per_vertex), 1)):
                if random.random() < probability_distribution:
                    edge = (vertex, generate_vertex_label(), generate_edge_weight())
                    edges.append(edge)
                    if enable_self_loops and vertex != label:
                        edge = (vertex, vertex, 0.0) 
                        edges.append(edge)

    graph.add_nodes_from(vertices, attributes=attributes.get(label, {}))
    graph.add_weighted_edges_from(edges)

    return graph, attributes

# Usage example
