import random
import string
from pathlib import Path

def generate_password(length: int, lowercase: bool, uppercase: bool, digits: bool, special_chars: bool, filename: str):
    if not all((isinstance(length, int), isinstance(lowercase, bool), isinstance(uppercase, bool), isinstance(digits, bool), isinstance(special_chars, bool))):
        raise TypeError(""All parameters must be of the correct type"")

    if length < 1:
        raise ValueError(""Password length must be greater than zero"")

    char_set = """"
    if lowercase: 
        char_set += string.ascii_lowercase
    if uppercase: 
        char_set += string.ascii_uppercase
    if digits: 
        char_set += string.digits
    if special_chars: 
        char_set += string.punctuation

    password = ''.join(random.choice(char_set) for _ in range(length))

    Path(filename).touch()  # Create the file if it doesn't exist

    with open(filename, 'a') as f:
        f.write(f""Password: {password}\n"")

