def calculate_area(land_plot_coords, algorithm='shoelace'):
    if len(land_plot_coords) < 3:
        raise ValueError(""A plot must have at least three vertices"")

    # Shoelace formula
    if algorithm == 'shoelace':
        area = 0.5 * abs(sum(x[i] * y[i+1] - x[i+1] * y[i]) for i in range(len(land_plot_coords)))

    # Triangulation method
    elif algorithm == 'triangulation':
        def sign(x):
            if x > 0:
                return 1
            elif x < 0:
                return -1
            else:
                return 0

        area = sum((x[i] * (y[(i+1)%len(land_plot_coords)]-y[(i-1)%len(land_plot_coords)])) for i in range(len(land_plot_coords)))
        area /= 2

    # Invalid algorithm
    else:
        raise ValueError(""Invalid algorithm, choose either 'shoelace' or 'triangulation'"")

    return abs(area)
