class Task:
    def __init__(self, id, narrative, timestamp):
        self.id = id
        self.narrative = narrative
        self.timestamp = timestamp

class TaskRoster:
    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        if task.timestamp > datetime.now():
            self.tasks.append(task)
            self.tasks.sort(key=lambda x: x.timestamp)

    def modify_task(self, id, new_narrative=None, new_timestamp=None):
        for task in self.tasks:
            if task.id == id:
                if new_narrative:
                    task.narrative = new_narrative
                if new_timestamp and new_timestamp > datetime.now():
                    task.timestamp = new_timestamp
                return
        print(""Task not found"")

    def display_tasks(self):
        for task in self.tasks:
            print(f""ID: {task.id}, Narrative: {task.narrative}, Timestamp: {task.timestamp}"")

    def remove_completed_tasks(self):
        self.tasks = [task for task in self.tasks if task.timestamp > datetime.now()]

def main():
    roster = TaskRoster()

    while True:
        print(""1. Add a new task"")
        print(""2. Modify an existing task"")
        print(""3. Display all tasks"")
        print(""4. Remove completed tasks"")
        print(""5. Quit"")

        choice = int(input(""Enter your choice: ""))

        if choice == 1:
            id = input(""Enter the task ID: "")
            narrative = input(""Enter the task narrative: "")
            timestamp = datetime.strptime(input(""Enter the start time (YYYY-MM-DD HH:MM): ""), ""%Y-%m-%d %H:%M"")
            roster.add_task(Task(id, narrative, timestamp))
        elif choice == 2:
            id = input(""Enter the task ID to modify: "")
            new_narrative = input(""Enter a new narrative (optional): "")
            new_timestamp = datetime.strptime(input(""Enter a new start time (YYYY-MM-DD HH:MM) or leave blank for no change: ""), ""%Y-%m-%d %H:%M"") if not new_timestamp else None
            roster.modify_task(id, new_narrative, new_timestamp)
        elif choice == 3:
            roster.display_tasks()
        elif choice == 4:
            roster.remove_completed_tasks()
        elif choice == 5:
            break
        else:
            print(""Invalid choice. Please try again."")

if __name__ == ""__main__"":
    main()
