import argparse
from pathlib import Path

def count_words(input_file_path: str, output_file_path=None) -> None:
    try:
        with open(input_file_path, 'r') as input_file:
            if output_file_path is None:
                output_file_path = f""{Path(input_file_path).stem}_word_count.txt""
            with open(output_file_path, 'w') as output_file:
                for line in input_file:
                    words = line.split()
                    word_count = len(words)
                    print(f""File: {input_file_path}, Word Count: {word_count}"")
    except FileNotFoundError:
        print(f""Error: The file '{input_file_path}' was not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description='Count the number of words in a file.')
    parser.add_argument('input_file', help='The input file path.', type=argparse.FileType('r'))
    parser.add_argument('-o', '--output-file', help='The output file path. If not provided, a default name will be generated based on the input file\'s name.', type=argparse.FileType('w'), default=None)
    parser.add_argument('--version', action='store_true', help='Display script version.')
    parser.add_argument('-h', '--help', action='store_true', help='Show this help message and exit.')

    args = parser.parse_args()

    if args.version:
        print(""Version 1.0"")
    elif args.help:
        parser.print_help()
    else:
        count_words(args.input_file.name, output_file_path=args.output_file)
