import pandas as pd
import boto3
import json
from simplejson import dumps

class DataProcessor:
    def process_data(self, dataset, filter_criteria=None, sort_field=None, aggregate_function=None):
        if filter_criteria:
            filtered_dataset = [data for data in dataset if all(data[key] == value for key, value in filter_criteria.items())]
        else:
            filtered_dataset = dataset

        if sort_field:
            sorted_dataset = sorted(filtered_dataset, key=lambda x: x[sort_field])
        else:
            sorted_dataset = filtered_dataset

        if aggregate_function:
            aggregated_data = {}
            for key, values in zip(*zip(*[data.values() for data in sorted_dataset]))[0]:
                aggregated_data[key] = aggregate_function(values)
        else:
            aggregated_data = [dict(zip(sorted_dataset[0].keys(), row)) for row in zip(*[data.values() for data in sorted_dataset])]

        return pd.DataFrame(aggregated_data).set_index('Index').to_dict()

def serialize_data(data):
    with open('output.json', 'w') as f:
        json.dump(dumps(data), f)

def upload_to_s3(bucket_name, file_path):
    s3 = boto3.client('s3')
    try:
        s3.put_object(Body=open(file_path, 'rb').read(), Bucket=bucket_name, Key=file_path)
        print(f""File uploaded successfully to {bucket_name}/{file_path}"")
    except Exception as e:
        print(f""Error uploading file: {e}"")

def test_data_processing():
    processor = DataProcessor()
    data = [{""Name"": ""John"", ""Age"": 30}, {""Name"": ""Jane"", ""Age"": 25}, {""Name"": ""Bob"", ""Age"": 35}]
    processed_data = processor.process_data(data, filter_criteria={""Age"": 30})
    assert isinstance(processed_data, dict)

def test_serialize():
    data = {'key1': 'value1', 'key2': 'value2'}
    serialize_data(data)
    with open('output.json') as f:
        json_data = json.load(f)
        assert json_data == {'key1': 'value1', 'key2': 'value2'}

def test_upload():
    bucket_name = 'my-bucket'
    file_path = 'path/to/file.json'
    upload_to_s3(bucket_name, file_path)
    # Delete the uploaded file for now
    s3 = boto3.client('s3')
    s3.delete_object(Bucket=bucket_name, Key=file_path)']",461,[0],[],True,0,0,0,

