import datetime

def get_user_input(prompt):
    while True:
        try:
            return input(prompt)
        except KeyboardInterrupt:
            print(""\nExiting the program."")
            exit()

def validate_age(age):
    if not age.isdigit():
        raise ValueError(""Age must be a positive integer."")
    return int(age)

def display_greeting(name, age=None):
    greeting = f""Hello, {name}!""
    if age is not None:
        birth_year = datetime.datetime.now().year - age
        greeting += f""\nYour year of birth was {birth_year}.""
    print(greeting)

def main():
    name = get_user_input(""Please enter your name: "")

    show_greeting_first = get_user_input(""Do you want to see your greeting message first (yes/no)? "").lower()

    if show_greeting_first == 'yes':
        display_greeting(name)

        age_input = get_user_input(""Please enter your current age (optional): "")

        try:
            age = validate_age(age_input)
            display_greeting(name, age)
        except ValueError as e:
            print(f""Error: {e}"")

    elif show_greeting_first == 'no':
        age_input = get_user_input(""Please enter your current age (optional): "")

        try:
            age = validate_age(age_input)
            display_greeting(name, age)

        except ValueError as e:
            print(f""Error: {e}"")

        display_greeting(name)

if __name__ == ""__main__"":
    main()
