import random
class RandomGenerator:
    def __init__(self, min_timestamp, max_timestamp, min_sensor, max_sensor):
        self.min_timestamp = min_timestamp
        self.max_timestamp = max_timestamp
        self.min_sensor = min_sensor
        self.max_sensor = max_sensor

    def generate_random_rx_tag(self):
        return f""RX_TAG_{random.randint(1, 1000)}""

    def generate_random_rnti(self):
        return random.randint(self.min_sensor, self.max_sensor)

    def generate_random_crc_flag(self):
        return bool(random.randint(1, 100) % 2)

def main():
    min_timestamp = 1
    max_timestamp = 1000
    min_sensor = 1
    max_sensor = 100000
    n = int(input(""Enter the number of entries: ""))

    if n <= 0:
        print(""Error: Invalid input size."")
        return

    generator = RandomGenerator(min_timestamp, max_timestamp, min_sensor, max_sensor)
    nfapi_crc_indication_pdu_t_list = []

    try:
        for _ in range(n):
            rx_tag = generator.generate_random_rx_tag()
            rnti = generator.generate_random_rnti()
            crc_flag = generator.generate_random_crc_flag()
            nfapi_crc_indication_pdu_t_list.append((rx_tag, rnti, crc_flag))

    except MemoryError:
        print(""Error: Memory allocation failed."")
        return

    for entry in nfaapi_crc_indication_pdu_t_list:
        print(f""RX Tag: {entry[0]}, RNTI: {entry[1]}, CRC Flag: {entry[2]}"")

if __name__ == ""__main__"":
    main()
